    from pymatgen.analysis.defects.ccd import HarmonicDefect
    from pathlib import Path

    file_path = Path("tool_source_code/pymatgen-analysis-defects/tests/test_files/v_Ga/ccd_0_-1")
    vaspruns = [Vasprun(file_path / f"{i}/vasprun.xml") for i in [0, 1, 2]]
    procar = Procar(file_path / "1/PROCAR")

    results = {
        "defect_band_index_mismatch": None,
        "defect_spin_index_mismatch": None
    }

    try:
        hd0 = HarmonicDefect.from_vaspruns(vaspruns, charge_state=0, procar=procar, store_bandstructure=True)

        # Check for defect band index mismatch
        try:
            hd0.defect_band = [(138, 0, 1), (139, 1, 1)]
            hd0.validate_defect_band_indices()  # Assuming this method checks for mismatches
        except ValueError:
            results["defect_band_index_mismatch"] = "Raises ValueError"

        # Check for defect spin index mismatch
        try:
            hd0.defect_band = [(138, 0, 1), (138, 1, 0)]
            hd0.validate_defect_band_indices()  # Assuming this method checks for mismatches
        except ValueError:
            results["defect_spin_index_mismatch"] = "Raises ValueError"

    except Exception as e:
        # If any other error occurs, set the properties to None
        results["defect_band_index_mismatch"] = None
        results["defect_spin_index_mismatch"] = None

    return results

