def calculate_material_properties():
    from pymatgen.core import Structure
    from pymatgen.core.lattice import Lattice
    from pathlib import Path

    def calculate_plane_spacing(lattice_matrix):
        try:
            lattice = Lattice(lattice_matrix)
            return lattice.d_hkl([1, 0, 0]), lattice.d_hkl([0, 1, 0]), lattice.d_hkl([0, 0, 1])
        except Exception:
            return None

    file_path = Path("tool_source_code/pymatgen-analysis-defects/tests/test_files/GaN.vasp")

    try:
        gan_struct = Structure.from_file(file_path)
        lattice_matrix = gan_struct.lattice.matrix
        plane_spacing = calculate_plane_spacing(lattice_matrix)
    except Exception:
        plane_spacing = None

    return {
        "plane_spacing": plane_spacing
    }

