        gan_struct = Structure.from_file(file_path / "GaN.vasp")

        # Substitution 1: Ga replaced by Mg and Ca
        substitution_1 = {"Ga": ["Mg", "Ca"]}
        generator_1 = SubstitutionGenerator(gan_struct, substitution_1)
        defects_1 = list(generator_1.enumerate_defects())

        # Check if all defects are of type Substitution
        results["defect_type"] = all(defect.defect_type == "Substitution" for defect in defects_1)

        # Get the set of replaced atoms for substitution 1
        replaced_atoms_1 = {defect.site.specie.symbol for defect in defects_1}
        results["replaced_atoms_set_1"] = replaced_atoms_1

        # Substitution 2: Ga replaced by Mg
        substitution_2 = {"Ga": "Mg"}
        generator_2 = SubstitutionGenerator(gan_struct, substitution_2)
        defects_2 = list(generator_2.enumerate_defects())

        # Get the set of replaced atoms for substitution 2
        replaced_atoms_2 = {defect.site.specie.symbol for defect in defects_2}
        results["replaced_atoms_set_2"] = replaced_atoms_2

