            results["replaced_atoms_set_2"] = None

    return results

def calculate_vacancy_properties():
    from pymatgen.core import Structure
    from pymatgen.analysis.defects.core import Vacancy
    from pymatgen.symmetry.analyzer import SpacegroupAnalyzer
    from pymatgen.core.periodic_table import Element
    from pathlib import Path

    file_path = Path("tool_source_code/pymatgen-analysis-defects/tests/test_files")
    try:
        gan_struct = Structure.from_file(file_path / "GaN.vasp")
    except Exception:
        return {prop: None for prop in [
            "symmetry_equivalence", "vacancy_string_representation", "vacancy_oxidation_state",
            "vacancy_charge_states", "vacancy_multiplicity", "vacancy_supercell_formula",
            "vacancy_name", "vacancy_self_equivalence", "vacancy_element_changes", "vacancy_latex_name"
        ]}

    try:
        s = gan_struct.copy()
        vac = Vacancy(s, s.sites[0])
        vac2 = Vacancy(s, s.sites[1])
    except Exception:
        return {prop: None for prop in [
            "symmetry_equivalence", "vacancy_string_representation", "vacancy_oxidation_state",
            "vacancy_charge_states", "vacancy_multiplicity", "vacancy_supercell_formula",
            "vacancy_name", "vacancy_self_equivalence", "vacancy_element_changes", "vacancy_latex_name"
        ]}

    properties = {}

    # Check symmetry equivalence
    try:
        symm_analyzer = SpacegroupAnalyzer(s)
        symm_struct = symm_analyzer.get_symmetrized_structure()
        properties["symmetry_equivalence"] = symm_struct.are_symmetrically_equivalent(vac.defect_site, vac2.defect_site)
    except Exception:
        properties["symmetry_equivalence"] = None

    # String representation
    try:
        properties["vacancy_string_representation"] = repr(vac)
    except Exception:
        properties["vacancy_string_representation"] = None

    # Oxidation state
    try:
        properties["vacancy_oxidation_state"] = vac.defect_site.specie.oxi_state
    except Exception:
        properties["vacancy_oxidation_state"] = None

    # Charge states
    try:
        properties["vacancy_charge_states"] = vac.defect_site.specie.oxidation_states
    except Exception:
        properties["vacancy_charge_states"] = None

    # Multiplicity
    try:
        properties["vacancy_multiplicity"] = vac.get_multiplicity()
    except Exception:
        properties["vacancy_multiplicity"] = None

    # Supercell formula
    try:
        properties["vacancy_supercell_formula"] = vac.defect_structure.composition.formula
    except Exception:
        properties["vacancy_supercell_formula"] = None

    # Name
    try:
        properties["vacancy_name"] = vac.name
    except Exception:
        properties["vacancy_name"] = None

    # Self equivalence
    try:
        properties["vacancy_self_equivalence"] = vac.defect_site.is_periodic_image(vac.defect_site)
    except Exception:
        properties["vacancy_self_equivalence"] = None

    # Element changes
    try:
        properties["vacancy_element_changes"] = vac.element_changes
    except Exception:
        properties["vacancy_element_changes"] = None

    # LaTeX name
    try:
        element = Element(vac.defect_site.specie.symbol)
        properties["vacancy_latex_name"] = f"v_{{{element.symbol}}}"
    except Exception:
        properties["vacancy_latex_name"] = None

    return properties
